package edu.smartstudy.parent;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="parent_student_links")public class ParentStudentLink{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="parent_id",nullable=false)private Long parentId;@Column(name="student_id",nullable=false)private Long studentId;@Column(nullable=false)private String status="PENDING";@Column(name="created_at",insertable=false,updatable=false)private Instant createdAt;protected ParentStudentLink(){}public ParentStudentLink(Long parent,Long student){parentId=parent;studentId=student;}public Long getId(){return id;}public Long getParentId(){return parentId;}public Long getStudentId(){return studentId;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public void accept(){status="APPROVED";}}
